#include "Serializer.h"
#include "LogUtils.h"

#include <iomanip>
#include <sstream>
#include <stdexcept>

namespace fluxus {
namespace {
Json optionalDate(const std::optional<DateTime>& value){return value?Json(value->iso()):Json(nullptr);}
std::optional<DateTime> readDate(const Json&object,const std::string&key){if(object.contains(key)&&object[key].is_string())return DateTime::fromIso(object[key].get<std::string>());return std::nullopt;}
std::string text(const Json&object,const std::string&key,const std::string&fallback=""){return object.contains(key)&&object[key].is_string()?object[key].get<std::string>():fallback;}
std::int64_t integer(const Json&object,const std::string&key,std::int64_t fallback=0){return object.contains(key)&&object[key].is_number()?object[key].get<std::int64_t>():fallback;}
bool boolean(const Json&object,const std::string&key,bool fallback=false){return object.contains(key)&&object[key].is_boolean()?object[key].get<bool>():fallback;}
std::string numberKey(double value){std::ostringstream out;out<<std::setprecision(15)<<value;return out.str();}
Json intMap(const std::map<int,int>&values){Json result=Json::object();for(const auto&[key,value]:values)result[std::to_string(key)]=value;return result;}
std::map<int,int> readIntMap(const Json&value){std::map<int,int>result;if(value.is_object())for(const auto&[key,item]:value.items())try{result[std::stoi(key)]=item.get<int>();}catch(...){}return result;}
Json denomStats(const DenomStats&stats){Json result=Json::object();for(const auto&[currency,values]:stats){Json item=Json::object();for(const auto&[denomination,count]:values)item[numberKey(denomination)]=count;result[currency]=std::move(item);}return result;}
DenomStats readDenomStats(const Json&value){DenomStats result;if(value.is_object())for(const auto&[currency,item]:value.items())for(const auto&[denomination,count]:item.items())try{result[currency][std::stod(denomination)]=count.get<int>();}catch(...){}return result;}
Json stringMap(const std::map<std::string,std::map<std::string,std::string>>&values){Json result=Json::object();for(const auto&[key,value]:values)result[key]=value;return result;}
std::map<std::string,std::map<std::string,std::string>> readStringMap(const Json&value){std::map<std::string,std::map<std::string,std::string>>result;if(value.is_object())for(const auto&[key,item]:value.items())for(const auto&[name,textValue]:item.items())result[key][name]=textValue.is_string()?textValue.get<std::string>():"";return result;}
Json health(const std::vector<HealthRecord>&records){Json result=Json::array();for(const auto&record:records)result.push_back({record.kind,record.state});return result;}
std::vector<HealthRecord> readHealth(const Json&value){std::vector<HealthRecord>result;if(value.is_array())for(const auto&item:value)if(item.is_array()&&item.size()>=2)result.push_back({item[0].get<std::string>(),item[1]});return result;}
Json banknote(const BanknoteSession&s){return {{"session_id",s.sessionId},{"events",s.events},{"start_timestamp",s.startTimestamp},{"first_date",s.firstDate},{"first_time",s.firstTime},{"uuid",s.uuid},{"status",s.status},{"denomination",s.denomination?Json(*s.denomination):Json(nullptr)},{"currency",s.currency?Json(*s.currency):Json(nullptr)},{"device_model",s.deviceModel},{"device_serial",s.deviceSerial},{"closed",s.closed},{"error_reason",s.errorReason}};}
BanknoteSession readBanknote(const Json&j){BanknoteSession s;s.sessionId=static_cast<int>(integer(j,"session_id"));s.events=j.value("events",Events{});s.startTimestamp=integer(j,"start_timestamp");s.firstDate=text(j,"first_date","?");s.firstTime=text(j,"first_time","?");s.uuid=text(j,"uuid","N/A");s.status=text(j,"status","INCOMPLETE");if(j.contains("denomination")&&j["denomination"].is_number())s.denomination=j["denomination"].get<int>();if(j.contains("currency")&&j["currency"].is_string())s.currency=j["currency"].get<std::string>();s.deviceModel=text(j,"device_model","Unknown");s.deviceSerial=text(j,"device_serial","N/A");s.closed=boolean(j,"closed");s.errorReason=text(j,"error_reason");return s;}
Json collection(const CollectionRecord&c){return {{"dt",c.dateTime.iso()},{"date_str",c.dateString},{"time_str",c.timeString},{"notes",intMap(c.notes)},{"raw",c.raw}};}
CollectionRecord readCollection(const Json&j){CollectionRecord c;c.dateTime=readDate(j,"dt").value_or(DateTime{});c.dateString=text(j,"date_str",c.dateTime.date());c.timeString=text(j,"time_str",c.dateTime.time());c.notes=readIntMap(j.value("notes",Json::object()));c.raw=text(j,"raw");return c;}
Json cash(const W2CashEvent&c){return {{"event_type",c.eventType},{"dt",optionalDate(c.dateTime)},{"timestamp",c.timestamp},{"boxes_delta",intMap(c.boxesDelta)},{"reject_delta",intMap(c.rejectDelta)},{"raw_by_nominal",intMap(c.rawByNominal)},{"total_cents",c.totalCents},{"raw_details",c.rawDetails}};}
W2CashEvent readCash(const Json&j){W2CashEvent c;c.eventType=text(j,"event_type");c.dateTime=readDate(j,"dt");c.timestamp=j.value("timestamp",0.0);c.boxesDelta=readIntMap(j.value("boxes_delta",Json::object()));c.rejectDelta=readIntMap(j.value("reject_delta",Json::object()));c.rawByNominal=readIntMap(j.value("raw_by_nominal",Json::object()));c.totalCents=integer(j,"total_cents");c.rawDetails=text(j,"raw_details");return c;}
Json lowLevel(const W2LowLevelSession&s,const std::optional<std::size_t>&index=std::nullopt){Json j={{"model",s.model},{"request_id",s.requestId?Json(*s.requestId):Json(nullptr)},{"job_id",s.jobId?Json(*s.jobId):Json(nullptr)},{"idx",s.idx},{"serial_path",s.serialPath},{"start_dt",optionalDate(s.startDateTime)},{"end_dt",optionalDate(s.endDateTime)},{"start_date",s.startDateString},{"start_time",s.startTimeString},{"commands",s.commands},{"results",s.results},{"status",s.status},{"error_detail",s.errorDetail},{"lcdm_status_code",s.lcdmStatusCode?Json(*s.lcdmStatusCode):Json(nullptr)},{"lcdm_device_code",s.lcdmDeviceCode?Json(*s.lcdmDeviceCode):Json(nullptr)},{"events",s.events},{"closed",s.closed}};if(index)j["index"]=*index;return j;}
std::shared_ptr<W2LowLevelSession> readLowLevel(const Json&j){auto s=std::make_shared<W2LowLevelSession>();s->model=text(j,"model");if(j.contains("request_id")&&j["request_id"].is_number())s->requestId=j["request_id"].get<int>();if(j.contains("job_id")&&j["job_id"].is_number())s->jobId=j["job_id"].get<int>();s->idx=text(j,"idx");s->serialPath=text(j,"serial_path");s->startDateTime=readDate(j,"start_dt");s->endDateTime=readDate(j,"end_dt");s->startDateString=text(j,"start_date","?");s->startTimeString=text(j,"start_time","?");s->commands=j.value("commands",Events{});s->results=j.value("results",Events{});s->status=text(j,"status","INCOMPLETE");s->errorDetail=text(j,"error_detail");if(j.contains("lcdm_status_code")&&j["lcdm_status_code"].is_number())s->lcdmStatusCode=j["lcdm_status_code"].get<int>();if(j.contains("lcdm_device_code")&&j["lcdm_device_code"].is_number())s->lcdmDeviceCode=j["lcdm_device_code"].get<int>();s->events=j.value("events",Events{});s->closed=boolean(j,"closed");return s;}
Json frontend(const W2WithdrawSession&s,const std::vector<std::shared_ptr<W2LowLevelSession>>&all){Json indices=Json::array();for(const auto&linked:s.lowLevelSessions){const auto it=std::find(all.begin(),all.end(),linked);if(it!=all.end())indices.push_back(static_cast<std::size_t>(it-all.begin()));}
    Json mismatch=Json::object();for(const auto&[key,value]:s.cassetteMismatchDetails)mismatch[std::to_string(key)]=value;
    return {{"trx",s.trx},{"events",s.events},{"start_dt",optionalDate(s.startDateTime)},{"end_dt",optionalDate(s.endDateTime)},{"start_date",s.startDateString},{"start_time",s.startTimeString},{"coupon",s.coupon},{"user_login",s.userLogin},{"group_uuid",s.groupUuid},{"balance_id",s.balanceId?Json(*s.balanceId):Json(nullptr)},{"transaction_id",s.transactionId?Json(*s.transactionId):Json(nullptr)},{"requested_amount",s.requestedAmount},{"dispensed_amount",s.dispensedAmount},{"commands",s.commands},{"dispensed_events",s.dispensedEvents},{"boxes",s.boxes},{"cassette_snapshot",s.cassetteSnapshot},{"status",s.status},{"error_detail",s.errorDetail},{"retry_count",s.retryCount},{"payout_coupon_status",s.payoutCouponStatus},{"recovery_coupon",s.recoveryCoupon},{"receipt_printed",s.receiptPrinted},{"dispenser_device_id",s.dispenserDeviceId},{"dispenser_model",s.dispenserModel},{"dispenser_vendor",s.dispenserVendor},{"lowlevel_indices",indices},{"suspicion_flags",s.suspicionFlags},{"cassette_mismatch",s.cassetteMismatch},{"cassette_mismatch_details",mismatch},{"cassette_mismatch_collective",s.cassetteMismatchCollective},{"cassette_mismatch_group_size",s.cassetteMismatchGroupSize}};}
std::shared_ptr<W2WithdrawSession> readFrontend(const Json&j,const std::vector<std::shared_ptr<W2LowLevelSession>>&low){auto s=std::make_shared<W2WithdrawSession>(text(j,"trx"));s->events=j.value("events",Events{});s->startDateTime=readDate(j,"start_dt");s->endDateTime=readDate(j,"end_dt");s->startDateString=text(j,"start_date","?");s->startTimeString=text(j,"start_time","?");s->coupon=text(j,"coupon");s->userLogin=text(j,"user_login");s->groupUuid=text(j,"group_uuid");if(j.contains("balance_id")&&j["balance_id"].is_number())s->balanceId=integer(j,"balance_id");if(j.contains("transaction_id")&&j["transaction_id"].is_number())s->transactionId=integer(j,"transaction_id");s->requestedAmount=integer(j,"requested_amount");s->dispensedAmount=integer(j,"dispensed_amount");s->commands=j.value("commands",Events{});s->dispensedEvents=j.value("dispensed_events",Events{});s->boxes=j.value("boxes",Events{});s->cassetteSnapshot=j.value("cassette_snapshot",std::vector<std::vector<int>>{});s->status=text(j,"status","INCOMPLETE");s->errorDetail=text(j,"error_detail");s->retryCount=static_cast<int>(integer(j,"retry_count"));s->payoutCouponStatus=text(j,"payout_coupon_status");s->recoveryCoupon=text(j,"recovery_coupon");s->receiptPrinted=boolean(j,"receipt_printed");s->dispenserDeviceId=text(j,"dispenser_device_id");s->dispenserModel=text(j,"dispenser_model");s->dispenserVendor=text(j,"dispenser_vendor");s->suspicionFlags=j.value("suspicion_flags",std::vector<std::vector<std::string>>{});s->cassetteMismatch=boolean(j,"cassette_mismatch");s->cassetteMismatchCollective=boolean(j,"cassette_mismatch_collective");s->cassetteMismatchGroupSize=static_cast<int>(integer(j,"cassette_mismatch_group_size",1));if(j.contains("cassette_mismatch_details")&&j["cassette_mismatch_details"].is_object())for(const auto&[key,value]:j["cassette_mismatch_details"].items())if(value.is_array()&&value.size()>=2)s->cassetteMismatchDetails[std::stoi(key)]={value[0].get<int>(),value[1].get<int>()};if(j.contains("lowlevel_indices")&&j["lowlevel_indices"].is_array())for(const auto&index:j["lowlevel_indices"]){const auto i=index.get<std::size_t>();if(i<low.size())s->lowLevelSessions.push_back(low[i]);}return s;}
void writeGzip(const std::string&path,const std::string&content){gzFile file=gzopen(path.c_str(),"wb");if(!file)throw std::runtime_error("Не удалось создать файл: "+path);gzbuffer(file,1024*1024);std::size_t offset=0;while(offset<content.size()){const int count=gzwrite(file,content.data()+offset,static_cast<unsigned>(std::min<std::size_t>(content.size()-offset,1024*1024)));if(count<=0){gzclose(file);throw std::runtime_error("Ошибка записи gzip: "+path);}offset+=static_cast<std::size_t>(count);}if(gzclose(file)!=Z_OK)throw std::runtime_error("Ошибка закрытия gzip: "+path);}
std::string readGzip(const std::string&path){gzFile file=gzopen(path.c_str(),"rb");if(!file)throw std::runtime_error("Не удалось открыть файл: "+path);gzbuffer(file,1024*1024);std::string result;std::vector<char>buffer(1024*1024);int count;while((count=gzread(file,buffer.data(),static_cast<unsigned>(buffer.size())))>0)result.append(buffer.data(),count);if(count<0){gzclose(file);throw std::runtime_error("Ошибка чтения gzip: "+path);}gzclose(file);return result;}
}

void AnalysisSerializer::save(const std::string&path,const AnalysisResult&result){
    Json lima={{"sessions",Json::array()},{"bnv_events",result.lima.bnvEvents},{"collections",Json::array()},{"stats",denomStats(result.lima.stats)},{"stats_by_device",Json::object()},{"device_models",stringMap(result.lima.deviceModels)},{"bnv_events_count",result.lima.bnvEventsCount},{"bnv_events_by_type",result.lima.bnvEventsByType},{"total_count",result.lima.totalCount},{"total_sum",result.lima.totalSum},{"lines_found",result.lima.linesFound},{"lines_parsed",result.lima.linesParsed}};
    for(const auto&s:result.lima.sessions)lima["sessions"].push_back(banknote(s));for(const auto&c:result.lima.collections)lima["collections"].push_back(collection(c));
    for(const auto&[model,serials]:result.lima.statsByDevice)for(const auto&[serial,currencies]:serials)lima["stats_by_device"][model][serial]=denomStats(currencies);
    Json low={{"sessions",Json::array()},{"lcdm_health",health(result.w2LowLevel.lcdmHealth)},{"lcdm_health_changes",health(result.w2LowLevel.lcdmHealthChanges)},{"dispensers",stringMap(result.w2LowLevel.dispensers)},{"lines_processed",result.w2LowLevel.linesProcessed},{"lines_matched",result.w2LowLevel.linesMatched}};for(const auto&s:result.w2LowLevel.sessions)low["sessions"].push_back(lowLevel(*s));
    Json front={{"sessions",Json::array()},{"cash_events",Json::array()},{"dispensers",stringMap(result.w2Frontend.dispensers)},{"lines_processed",result.w2Frontend.linesProcessed},{"lines_matched",result.w2Frontend.linesMatched}};for(const auto&s:result.w2Frontend.sessions)front["sessions"].push_back(frontend(*s,result.w2LowLevel.sessions));for(const auto&c:result.w2Frontend.cashEvents)front["cash_events"].push_back(cash(c));
    Json root={{"version",CurrentVersion},{"saved_at",DateTime::now().iso()},{"source_files",result.sourceFiles},{"lima",lima},{"w2_frontend",front},{"w2_lowlevel",low}};writeGzip(path,root.dump());
}

AnalysisResult AnalysisSerializer::load(const std::string&path){const auto root=Json::parse(readGzip(path));const int version=static_cast<int>(integer(root,"version"));if(version!=1&&version!=2)throw std::runtime_error("Несовместимая версия файла анализа");AnalysisResult result;result.version=version;result.sourceFiles=root.value("source_files",std::vector<std::string>{});result.savedAt=readDate(root,"saved_at").value_or(DateTime{});
    const auto lima=root.value("lima",Json::object());for(const auto&j:lima.value("sessions",Json::array()))result.lima.sessions.push_back(readBanknote(j));result.lima.bnvEvents=lima.value("bnv_events",Events{});for(const auto&j:lima.value("collections",Json::array()))result.lima.collections.push_back(readCollection(j));result.lima.stats=readDenomStats(lima.value("stats",Json::object()));
    if(lima.contains("stats_by_device"))for(const auto&[model,serials]:lima["stats_by_device"].items())for(const auto&[serial,currencies]:serials.items())result.lima.statsByDevice[model][serial]=readDenomStats(currencies);
    result.lima.deviceModels=readStringMap(lima.value("device_models",Json::object()));if(lima.contains("bnv_events_count"))for(const auto&[key,value]:lima["bnv_events_count"].items())result.lima.bnvEventsCount[key]=value.get<int>();if(lima.contains("bnv_events_by_type"))for(const auto&[validator,events]:lima["bnv_events_by_type"].items())for(const auto&[key,value]:events.items())result.lima.bnvEventsByType[validator][key]=value.get<int>();result.lima.totalCount=integer(lima,"total_count");result.lima.totalSum=lima.value("total_sum",0.0);result.lima.linesFound=integer(lima,"lines_found");result.lima.linesParsed=integer(lima,"lines_parsed");
    const auto low=root.value("w2_lowlevel",Json::object());for(const auto&j:low.value("sessions",Json::array()))result.w2LowLevel.sessions.push_back(readLowLevel(j));result.w2LowLevel.lcdmHealth=readHealth(low.value("lcdm_health",Json::array()));result.w2LowLevel.lcdmHealthChanges=readHealth(low.value("lcdm_health_changes",Json::array()));result.w2LowLevel.dispensers=readStringMap(low.value("dispensers",Json::object()));result.w2LowLevel.linesProcessed=integer(low,"lines_processed");result.w2LowLevel.linesMatched=integer(low,"lines_matched");
    const auto front=root.value("w2_frontend",Json::object());for(const auto&j:front.value("sessions",Json::array()))result.w2Frontend.sessions.push_back(readFrontend(j,result.w2LowLevel.sessions));result.w2Frontend.restoreSessions(result.w2Frontend.sessions);for(const auto&j:front.value("cash_events",Json::array()))result.w2Frontend.cashEvents.push_back(readCash(j));result.w2Frontend.dispensers=readStringMap(front.value("dispensers",Json::object()));result.w2Frontend.linesProcessed=integer(front,"lines_processed");result.w2Frontend.linesMatched=integer(front,"lines_matched");return result;}

} // namespace fluxus
